    Arrays.fill(parent, -1);
    parent[0] = 0;
    boolean[] visited = new boolean[n];
    visited[0] = true;

    int time = 0;
    while (true) {
        int next = -1;
        int minTime = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            if (visited[i] && hasApple[i]) {
                time += 2;
                visited[i] = false;
                break;
            }
            if (visited[i] && parent[i] != -1 && !visited[parent[i]]) {
                next = parent[i];
                minTime = Math.min(minTime, time);
            }
        }
        if (next == -1) break;
        visited[next] = true;
        time += 1;
    }
    return time;
}
