private static void reverse(StringBuilder sb) {
    int low = 0;
    int high = sb.length() - 1;
    while (low < high) {
        char temp = sb.charAt(low);
        sb.setCharAt(low, sb.charAt(high));
        sb.setCharAt(high, temp);
        low++;
        high--;
    }
}

